 <script>
(function(){
 const form=document.querySelector('.menu-toolbar');
 if(!form)return;
 const input=form.querySelector('input[name="q"]');
 const results=document.querySelector('.menu-results');
 const count=document.querySelector('.menu-catalog-head p');
 const sort=form.querySelector('select[name="sort"]');
 let timer=null,request=null;
 function syncLinks(params){
  document.querySelectorAll('.menu-category-nav .menu-chip').forEach(function(link){
   const url=new URL(link.href,window.location.href);
   const query=params.get('q')||'';
   const order=params.get('sort')||'popular';
   if(query)url.searchParams.set('q',query);else url.searchParams.delete('q');
   if(order!=='popular')url.searchParams.set('sort',order);else url.searchParams.delete('sort');
   url.searchParams.delete('pg');
   link.href=url.toString();
  });
  let clear=form.querySelector('.menu-clear');
  const hasFilters=(params.get('q')||'')!==''||(params.get('cat')||'')!==''||(params.get('sort')||'popular')!=='popular';
  if(hasFilters){
   if(!clear){clear=document.createElement('a');clear.className='menu-clear';clear.textContent='Xóa lọc';form.appendChild(clear);}
   clear.href='index.php?page=cuahang';
  }else if(clear){clear.remove();}
 }
 async function updateMenu(){
  const params=new URLSearchParams(new FormData(form));
  params.delete('pg');
  const url=new URL(window.location.href);
  url.search=params.toString();
  if(request)request.abort();
  request=new AbortController();
  form.setAttribute('aria-busy','true');
  try{
   const response=await fetch(url.toString(),{signal:request.signal,headers:{'X-Requested-With':'XMLHttpRequest'}});
   if(!response.ok)throw new Error('Không thể tải thực đơn');
   const html=await response.text();
   const doc=new DOMParser().parseFromString(html,'text/html');
   const nextResults=doc.querySelector('.menu-results');
   if(!nextResults)return;
   results.innerHTML=nextResults.innerHTML;
   const nextCount=doc.querySelector('.menu-catalog-head p');
   if(count&&nextCount)count.textContent=nextCount.textContent;
   history.replaceState(null,'',url.toString());
   syncLinks(params);
  }catch(error){if(error.name!=='AbortError')console.error(error);}
  finally{form.removeAttribute('aria-busy');}
 }
 input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(updateMenu,300);});
 form.addEventListener('submit',function(event){event.preventDefault();clearTimeout(timer);updateMenu();});
 if(sort)sort.addEventListener('change',updateMenu);
})();
</script><?php render_footer();exit;
 }function is_drink_category($category) { return preg_match('/cà phê|espresso|cold brew|trà|matcha|chocolate|đá xay|sữa|soda|sinh tố|đồ uống|nước ép/iu', (string)$category) === 1; }
function drink_percent($value) { $allowed=[0,25,50,75,100];$value=(int)$value;return in_array($value,$allowed,true)?$value:100; }
