if ($page === 'product') {
 $id=(int)($_GET['id']??0);
 $q=$db->prepare('SELECT p.*,c.name AS category_name FROM san_pham p JOIN danh_muc c ON c.id=p.category_id WHERE p.id=? AND p.active=1 AND c.active=1');
 $q->bind_param('i',$id);$q->execute();$p=$q->get_result()->fetch_assoc();$q->close();
 if(!$p)go('index.php?page=cuahang');
 $cid=(int)$p['category_id'];$relatedQuery=$db->prepare('SELECT * FROM san_pham WHERE id<>? AND active=1 ORDER BY (category_id=?) DESC,featured DESC,id DESC LIMIT 4');$relatedQuery->bind_param('ii',$id,$cid);$relatedQuery->execute();$related=$relatedQuery->get_result();
 $isDrink=is_drink_category($p['category_name']);$inStock=(int)$p['stock']>0;$lowStock=$inStock&&(int)$p['stock']<5;
